"""Symptom-led close-ups. Shared palette, 200–220px subject width on 340px crop.
No magnifier badges, furniture, anatomy cutaways or full-body figures.
"""
from clinic_character_master import PALETTE

def p(d,c='none',s='none',w=1.4):
 return f'<path d="{d}" fill="{c}" stroke="{s}" stroke-width="{w}" stroke-linecap="round" stroke-linejoin="round"/>'
def skin(d):return p(d,'var(--skin)')
def shadow(d):return p(d,'var(--skin_shadow)')
def crease(d):return p(d,s='#b69079',w=1.3)
def pain(d):return p(d,s='var(--terracotta)',w=2.5)
def accent(x,y):
 return f'<ellipse cx="{x}" cy="{y}" rx="13" ry="10" fill="var(--terracotta)" opacity=".2"/>'
def wrap(content):
 style=';'.join(f'--{k}:{v}' for k,v in PALETTE.items())
 return f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="30 26 340 306" style="{style}" data-illustration-system="symptom-closeup-v1" aria-hidden="true" focusable="false"><ellipse cx="202" cy="193" rx="121" ry="129" fill="var(--cream)"/><ellipse cx="201" cy="296" rx="91" ry="4" fill="#ded6c7" opacity=".4"/>{content}</svg>'

